/* =============================== FUNCTIONAL (medium) PAGES =============================== */
const dirPage = ({ nav, title, desc, actions, kpis, tableId, cfg, extra, note }) => { const n = NAVIDX[nav]; const tr = navTrail(nav); return { html: `<div class="page">${phead({ crumbs: tr.map(x => [x[0], x[1] || S.route]), title: title || t(nav), desc, actions: (actions || '') + `<button class="btn" data-act="export" data-what="${esc(t(nav))}">${ic('download')}Export</button>` })}${note ? `<div class="banner info" style="border:1px solid var(--info-line);border-radius:10px;margin-bottom:14px">${ic('info')}<span>${note}</span></div>` : ''}${kpis ? gate(kpiRow(kpis), 2) : ''}<section class="panel" style="${kpis ? 'margin-top:14px' : ''}">${defTable(tableId, cfg)}</section>${extra || ''}</div>` }; };
const lvlNote = () => `${mockmark()} ${L3(['Fungsional — data simulasi', 'Functional — mock data', 'وظيفي — بيانات تجريبية'])}`;

route('/travel/branches', () => dirPage({ nav: 'travel_branch', desc: L3(['Cabang milik tenant Travel. Default subscription mencakup maksimal 2 cabang; cabang tambahan berbayar (add-on).', 'Branches owned by Travel tenants. Default subscription covers up to 2 branches; extra branches are paid add-ons.', 'فروع الشركات. يشمل الاشتراك فرعين.']), tableId: 'branches', kpis: [{ k: L3(['Cabang aktif', 'Active branches', 'فروع نشطة']), v: fN(BRANCHES.filter(b => b.status === 'active').length) }, { k: 'Add-on', v: fN(BRANCHES.filter(b => b.paid).length) }, { k: L3(['Tenant penuh kuota', 'Tenants at quota', 'شركات بلغت الحصة']), v: fN(TRAVELS.filter(x => x.branch.used >= x.branch.quota).length) }, { k: L3(['Rata-rata / tenant', 'Avg / tenant', 'المتوسط']), v: fN(BRANCHES.length / TRAVELS.length, { maximumFractionDigits: 1 }) }],
  cfg: { name: 'Cabang', search: r => r.name + r.id + travelById(r.travel).name + r.city, rows: () => BRANCHES, route: r => '/travel/' + r.travel + '/branches', filters: [{ v: 'all', label: t('f_all'), fn: () => true }, { v: 'def', label: 'Default', fn: r => !r.paid }, { v: 'add', label: 'Add-on', fn: r => r.paid }], cols: [{ k: 'name', label: L3(['Cabang', 'Branch', 'الفرع']), render: r => `<b>${esc(r.name)}</b><div class="muted mono" style="font-size:11.5px">${r.id}</div>` }, { k: 'travel', label: 'Travel', render: r => esc(travelById(r.travel).name) }, { k: 'city', label: L3(['Kota', 'City', 'المدينة']) }, { k: 'head', label: L3(['Kepala cabang', 'Branch head', 'مدير الفرع']) }, { k: 'paid', label: L3(['Tipe', 'Type', 'النوع']), render: r => `<span class="chip">${r.paid ? 'Add-on' : 'Default'}</span>` }, { k: 'status', label: t('status'), render: r => st(r.status) }] } }));
function licRows() { const out = []; TRAVELS.forEach(tr => tr.lic.forEach((l, i) => out.push({ id: tr.id + '-' + l.type, tr, l, i }))); return out; }
const licCfg = () => ({ name: 'Legalitas', placeholder: t('tr_search'), search: r => r.tr.name + r.tr.id + r.l.type + r.l.no, rows: licRows, route: r => '/travel/' + r.tr.id + '/legal', filters: [{ v: 'all', label: t('f_all'), fn: () => true }, ...['under_review', 'submitted', 'expiring', 'expired', 'rejected', 'verified'].map(s => ({ v: s, label: L3(STATUS[s].slice(2)), fn: r => r.l.status === s }))], bulk: [{ k: 'remind', label: L3(['Kirim pengingat', 'Send reminder', 'إرسال تذكير']) }],
  cols: [{ k: 'tr', label: 'Travel', render: r => ent(r.tr.name, `<span class="mono">${r.tr.id}</span>`, r.tr.color), sv: r => r.tr.name }, { k: 'type', label: L3(['Izin', 'License', 'الترخيص']), render: r => `<b>${r.l.type}</b>`, sv: r => r.l.type }, { k: 'no', label: L3(['Nomor', 'Number', 'الرقم']), render: r => `<span class="mono">${esc(r.l.no)}</span>`, sort: false }, { k: 'exp', label: L3(['Berlaku s.d.', 'Valid until', 'صالح حتى']), render: r => `${fD(r.l.exp)}<div class="muted" style="font-size:11.5px">${rel(r.l.exp)}</div>`, sv: r => r.l.exp }, { k: 'status', label: t('status'), render: r => st(r.l.status), sv: r => r.l.status }],
  card: r => `${ent(r.tr.name, r.l.type + ' · ' + esc(r.l.no), r.tr.color)}<div class="row">${st(r.l.status)}<span class="muted" style="font-size:12px">${fD(r.l.exp)}</span></div>` });
route('/travel/legal', () => dirPage({ nav: 'travel_legal', desc: L3(['Perizinan per layanan: BPW (tour), PPIU (umrah), PIHK (haji khusus). Lifecycle: Draft → Submitted → Under Review → Verified / Rejected → Expired.', 'Licensing per service: BPW (tour), PPIU (umrah), PIHK (special hajj). Lifecycle: Draft → Submitted → Under Review → Verified / Rejected → Expired.', 'التراخيص حسب الخدمة.']), tableId: 'lic', cfg: licCfg(), kpis: ['verified', 'under_review', 'expiring', 'expired'].map(s => ({ k: L3(STATUS[s].slice(2)), v: fN(licRows().filter(r => r.l.status === s).length) })) }));
route('/compliance/legal', () => dirPage({ nav: 'legal', desc: L3(['Pandangan compliance atas seluruh dokumen legal ekosistem (Travel & Vendor).', 'Compliance view of all legal documents in the ecosystem (Travel & Vendor).', 'عرض الامتثال لكل المستندات.']), tableId: 'lic2', cfg: licCfg() }));
const subsCfg = () => ({ name: 'Subscription', placeholder: t('tr_search'), search: r => r.name + r.id, rows: () => TRAVELS, route: r => '/travel/' + r.id + '/subscription', filters: [{ v: 'all', label: t('f_all'), fn: () => true }, ...['pending', 'active', 'trial', 'grace', 'suspended', 'expired', 'cancelled'].map(s => ({ v: s, label: L3(STATUS[s].slice(2)), fn: r => r.sub.state === s }))],
  cols: [{ k: 'name', label: 'Travel', render: r => ent(r.name, `<span class="mono">${r.id}</span>`, r.color) }, { k: 'plan', label: 'Plan', render: r => `<b>${r.sub.plan}</b><div class="muted tnum" style="font-size:11.5px">${money(r.sub.price, true)}/bln</div>`, sv: r => r.sub.price }, { k: 'state', label: 'Lifecycle', render: r => st(r.sub.state), sv: r => r.sub.state }, { k: 'renew', label: L3(['Perpanjangan', 'Renewal', 'التجديد']), render: r => `${fD(r.sub.renew)}<div class="muted" style="font-size:11.5px">${rel(r.sub.renew)}</div>`, sv: r => r.sub.renew }, { k: 'br', label: L3(['Cabang', 'Branches', 'الفروع']), render: branchCell, sv: r => r.branch.used }, { k: 'web', label: 'Website', render: r => st(['active', 'grace', 'trial'].includes(r.sub.state) ? 'published' : 'unpublished'), sort: false }] });
route('/travel/subscription', () => dirPage({ nav: 'travel_subs', desc: 'Pending → Active → Grace Period → Suspended → Expired → Cancelled. ' + L3(['Website Travel mengikuti entitlement subscription.', 'Travel Website follows subscription entitlement.', 'الموقع يتبع الاشتراك.']), tableId: 'subs', cfg: subsCfg(), kpis: ['active', 'grace', 'suspended', 'pending'].map(s => ({ k: L3(STATUS[s].slice(2)), v: fN(TRAVELS.filter(x => x.sub.state === s).length) })) }));
route('/saas/subscription', () => dirPage({ nav: 'sub', desc: L3(['Semua subscription SaaS (saat ini: tenant Travel). Subscription langsung dibayar; trial hanya via request.', 'All SaaS subscriptions (currently: Travel tenants). Paid upfront; trial only via request.', 'كل الاشتراكات.']), tableId: 'subs2', cfg: subsCfg(), kpis: [{ k: 'MRR', v: money(TRAVELS.filter(x => ['active', 'grace'].includes(x.sub.state)).reduce((s, x) => s + x.sub.price + x.sub.addonBranch * 45e4, 0)) }, { k: 'Active', v: fN(TRAVELS.filter(x => x.sub.state === 'active').length) }, { k: 'Grace', v: fN(TRAVELS.filter(x => x.sub.state === 'grace').length) }, { k: 'Churn 30d', v: TRAVELS.length ? pct(TRAVELS.filter(x => ['expired', 'cancelled'].includes(x.sub.state) && (x.sub.endedAt || x.sub.renew || 0) >= nowTs() - 30 * D).length / TRAVELS.length * 100) : '—' }] }));

