PAGES.placeholder = id => {
  const n = NAVIDX[id]; const b = BP[id] || { s: [], e: [], l: [], r: [] }; const tr = navTrail(id);
  const html = `<div class="page">${phead({ crumbs: tr.map(x => [x[0], x[1] || S.route]), title: t(id), desc: t('ph_desc'), actions: `<span class="st neu">${ic('grid')}${esc(t('ph_status'))}</span><a class="btn" href="#/ia">${ic('grid')}${t('iamap')}</a>` })}
  <div class="grid g12"><div class="c8" style="display:grid;gap:14px;align-content:start">
   ${pnl(t('planned'), b.s.length ? `<div style="display:grid;gap:8px">${b.s.map(s => `<div class="bp-sec">${ic('panel', 'sm')}<span style="flex:1">${esc(s)}</span><span class="chip">${L3(['direncanakan', 'planned', 'مخطط'])}</span></div>`).join('')}</div>` : '<span class="muted">—</span>', { icon: 'list' })}
   <section class="bp" aria-label="skeleton preview"><div class="panel-h" style="border-bottom:1px dashed var(--line-strong)"><h3>${ic('eye', 'sm')}${L3(['Pratinjau layout (skeleton)', 'Layout preview (skeleton)', 'معاينة التخطيط'])}</h3></div><div style="padding:14px;display:grid;gap:10px"><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">${[1, 2, 3, 4].map(() => `<div style="border:1px dashed var(--line-strong);border-radius:8px;padding:10px;display:grid;gap:6px"><div class="skel" style="width:50%;height:9px;animation:none"></div><div class="skel" style="width:70%;height:16px;animation:none"></div></div>`).join('')}</div><div style="border:1px dashed var(--line-strong);border-radius:8px;padding:0">${skel(4).replace(/class="skel"/g, 'class="skel" style="animation:none"')}</div></div></section>
  </div><div class="c4" style="display:grid;gap:14px;align-content:start">
   ${b.l.length ? pnl(t('lifecycle'), `<div style="display:flex;gap:6px;flex-wrap:wrap">${b.l.map(s => STATUS[s] ? st(s) : `<span class="chip">${esc(s)}</span>`).join(`<span class="muted">→</span>`)}</div>`, { icon: 'refresh' }) : ''}
   ${pnl(t('entities'), b.e.length ? b.e.map(e => `<div class="mono" style="font-size:11.5px;padding:6px 8px;background:var(--surface-2);border-radius:6px;margin-bottom:6px;overflow-wrap:anywhere">${esc(e)}</div>`).join('') : '<span class="muted">—</span>', { icon: 'layers' })}
   ${pnl(t('relations'), b.r.length ? `<div style="display:flex;gap:6px;flex-wrap:wrap">${b.r.filter(r => NAVIDX[r]).map(r => `<a class="chip" href="#${NAVIDX[r].r || (NAVIDX[r].kids || [{}])[0].r}">${ic(NAVIDX[r].i, 'sm')}${esc(t(r))}</a>`).join('')}</div>` : '<span class="muted">—</span>', { icon: 'link' })}
   ${pnl(t('perms'), `<span class="chip mono">${esc(n.p)}</span> <span class="chip mono">${esc(n.p.split('.')[0])}.manage</span>`, { icon: 'lock' })}
   ${pnl(t('states_req'), `<div style="display:flex;gap:6px;flex-wrap:wrap">${['Loading', 'Empty', 'Error', 'No permission', 'No result', 'Offline', 'Success', 'Warning', 'Destructive confirm'].map(s => `<span class="chip">${s}</span>`).join('')}</div>`, { icon: 'activity' })}
  </div></div></div>`;
  return { html };
};

