route('/ia', () => { const lv = { hi: 0, md: 0, ph: 0 }; Object.values(NAVIDX).forEach(n => { if (n.lvl) lv[n.lvl]++; }); lv.hi += 2;
  const html = `<div class="page">${phead({ crumbs: [[BRAND.name, '/overview'], [t('iamap'), '/ia']], title: t('iamap'), desc: L3(['Seluruh information architecture Control Center: Group → Module → Submodule. Tanda menunjukkan kedalaman implementasi iterasi ini.', 'The full Control Center information architecture: Group → Module → Submodule. Markers show implementation depth in this iteration.', 'البنية الكاملة للمعلومات.']) })}
  <div class="kpis" style="margin-bottom:14px">${[[t('lvl_hi'), lv.hi, 'hi'], [t('lvl_md'), lv.md, 'md'], [t('lvl_ph'), lv.ph, 'ph'], ['Route', Object.values(NAVIDX).filter(n => n.r).length + 6, null]].map(k => `<div class="kpi"><div class="k">${k[2] ? `<span class="lvl ${k[2]}"></span>` : ''}${esc(k[0])}</div><div class="v">${k[1]}</div></div>`).join('')}</div>
  <div class="panel" style="padding:10px 14px;margin-bottom:14px;font-size:12.5px;display:flex;gap:16px;flex-wrap:wrap"><span><span class="lvl hi" style="display:inline-block"></span> ${t('lvl_hi')}: Overview, Approval Center, Travel Directory, Travel Detail (/travel/[travelId]), Omnichannel Inbox, Ads Overview, Campaign Detail (/ads/campaign/[id]), Finance Overview</span><span><span class="lvl md" style="display:inline-block"></span> ${t('lvl_md')}</span><span><span class="lvl ph" style="display:inline-block"></span> ${t('lvl_ph')}</span></div>
  <div class="iamap">${NAV.map(g => `<div class="grp"><h4>${esc(t(g.g))}</h4><ul>${g.items.map(m => `<li>${m.kids ? `<a href="#${m.kids[0].r}"><span class="lvl ${m.kids.some(k => k.lvl === 'hi') ? 'hi' : m.kids.some(k => k.lvl === 'md') ? 'md' : 'ph'}"></span>${ic(m.i, 'sm')}<b>${esc(t(m.id))}</b></a><ul>${m.kids.map(k => `<li><a href="#${k.r}"><span class="lvl ${k.lvl}"></span>${esc(t(k.id))}<span class="muted mono" style="margin-inline-start:auto;font-size:10.5px">${k.r}</span></a></li>`).join('')}</ul>` : `<a href="#${m.r}"><span class="lvl ${m.lvl}"></span>${ic(m.i, 'sm')}${esc(t(m.id))}<span class="muted mono" style="margin-inline-start:auto;font-size:10.5px">${m.r}</span></a>`}</li>`).join('')}</ul></div>`).join('')}
  <div class="grp"><h4>${L3(['Route dinamis', 'Dynamic routes', 'مسارات ديناميكية'])}</h4><ul>${[['/travel/[travelId]', '/travel/' + ((TRAVELS[0]||{}).id||'')], ['/travel/[travelId]/[tab]', '/travel/' + TRAVELS[1].id + '/legal'], ['/vendor/[vendorId]', '/vendor/' + ((VENDORS[0]||{}).id||"")], ['/booking/[bookingId]', '/booking/' + ((BOOKINGS[0]||{}).id||"")], ['/finance/payment/[paymentId]', '/finance/payment/' + ((PAYMENTS[0]||{}).id||"")], ['/ads/campaign/[campaignId]', '/ads/campaign/' + ((CAMPAIGNS[0]||{}).id||"")], ['/omni/inbox/[conversationId]', '/omni/inbox/' + ((CONVERSATIONS[0]||{}).id||"")], ['/approval/[approvalId]', '/approval/' + ((APPROVALS[0]||{}).id||"")]].map(r => `<li><a href="#${r[1]}"><span class="lvl hi"></span><span class="mono" style="font-size:11.5px">${r[0]}</span></a></li>`).join('')}</ul></div></div>
  <div class="section-title"><h2>${L3(['Yang masih perlu ditambahkan', 'Still to be added', 'ما يجب إضافته'])}</h2><span class="rule"></span></div>
  <div class="grid g3">${pnl(L3(['Sudah berfungsi (client-side)', 'Working now (client-side)', 'يعمل الآن']), `<ul style="margin:0;padding-inline-start:18px;display:grid;gap:4px;font-size:13px"><li>Semua ${Object.values(NAVIDX).filter(n => n.r).length} modul: list, filter, sort, detail, create/edit</li><li>Lifecycle & state transition dengan konfirmasi + alasan</li><li>Audit Log untuk setiap aksi sensitif</li><li>Permission matrix yang mengubah menu & aksi</li><li>Export CSV, realtime simulasi, ID/EN/AR + RTL</li></ul>`, { icon: 'check' })}${pnl(L3(['Butuh keputusan bisnis', 'Needs business decisions', 'قرارات مطلوبة']), `<ul style="margin:0;padding-inline-start:18px;display:grid;gap:4px;font-size:13px"><li>Aturan komisi Affiliate lintas Travel</li><li>Kebijakan refund per kategori paket</li><li>Threshold approval withdrawal</li><li>Model atribusi default Ads</li><li>Grace period (hari) per plan</li></ul>`, { icon: 'info' })}${pnl(L3(['Belum: integrasi backend', 'Not yet: backend integration', 'لم يتم: الخادم']), `<ul style="margin:0;padding-inline-start:18px;display:grid;gap:4px;font-size:13px"><li>${SB.on ? 'Data tersimpan di Supabase (Postgres) ✓' : 'Mode lokal: data reset saat reload'}</li><li>Auth per-user (Supabase Auth) → can()</li><li>WebSocket event bus → realtime()</li><li>Search API, audit service (append-only)</li><li>Gateway, WA BSP, ad server Segaloka (web + app) sungguhan</li></ul>`, { icon: 'plug' })}</div></div>`;
  return { html }; });
